import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash, randomUUID } from 'node:crypto';
import { handleLearning, isSelfContainedLearningCalculation } from './learning.mjs';
import { createAnthropicPromptCache } from './ai-prompt-cache.mjs';
import { HOMEWORK_PROMPT_VERSION, HOMEWORK_SHARED_GUIDANCE } from './prompts/homework-v1.mjs';
import { STUDENT_STYLE_GUIDANCE } from './prompts/student-style-v1.mjs';
import { ASSIGNMENT_FORMAT_GUIDANCE } from './assignment-format.mjs';
import { HOMEWORK_EVALUATION_CASES, HOMEWORK_CACHE_PROBE_CASES } from '../test-support/homework-evaluation.mjs';
import { learningTestD1, learningMemoryStorage, learningProviderFixture, learningTestOrigin as origin, learningTestAlice as alice, learningTestBob as bob } from '../test-support/learning-memory.mjs';

function fixture(t,overrides={}){
  const DB=learningTestD1(t),storage=learningMemoryStorage(),provider=learningProviderFixture(),sourceCalls=[];
  let explicitProviderOverride=false;const originalOverride=provider.setOverride;provider.setOverride=value=>{explicitProviderOverride=typeof value==='function';originalOverride(value);};
  const fetcher=async(url,options)=>{const body=JSON.parse(options.body),response=await provider.fetcher(url,options);if(!explicitProviderOverride&&!body.tools){const context=JSON.parse(body.messages[0].content),calculation=context.calculationEvidence;if(calculation){const data=await response.json(),artifact=JSON.parse(data.content[0].text);artifact.summary='The solution is x = '+calculation.solution+'.';artifact.content='The answer is x = '+calculation.solution+'.\n'+calculation.steps.join('\n')+'\nSubstitution gives '+calculation.leftValue+' on each side.'+(context.sources.length?' Source context ['+context.sources[0].id+'].':'');data.content[0].text=JSON.stringify(artifact);return Response.json(data);}}return response;};
  const env={DB,LEARNING_ENABLED:'1',LEARNING_PILOT_ENABLED:'1',LEARNING_AI_CONFIGURED:true,LEARNING_RESOLVE_KEY:async()=>'synthetic-learning-api-key-not-real',LEARNING_FETCH:fetcher,LEARNING_PROMPT_CACHE_PREPARE:createAnthropicPromptCache().prepare,LEARNING_DATA_FETCH:storage.fetcher,LEARNING_HASH_SALT:'synthetic-learning-private-usage-salt',LEARNING_SOURCE_FETCH:async(url,options)=>{sourceCalls.push({url,options});return httpEvidenceResponse();},PORTAL_SUPABASE_URL:'https://identity.example.invalid',PORTAL_SUPABASE_PUBLISHABLE_KEY:'sb_publishable_synthetic_learning_test',...overrides};
  async function call(path,{method='GET',body,owner=alice,headers={},env:extra={}}={}){
    const h={...headers};if(method!=='GET'){if(!Object.hasOwn(h,'Origin'))h.Origin=origin;if(!Object.hasOwn(h,'X-Learning-Request'))h['X-Learning-Request']='1';if(!Object.hasOwn(h,'Content-Type'))h['Content-Type']='application/json';}
    const response=await handleLearning(new Request(origin+'/api/learning'+path,{method,headers:h,...(body===undefined?{}:{body:JSON.stringify(body)})}),{...env,PORTAL_USER:owner?{id:'sb-'+owner,displayName:owner===alice?'Alice':'Bob'}:null,PORTAL_USER_ACCESS_TOKEN:owner===alice?'token-alice':'token-bob',...extra});
    return{status:response.status,headers:response.headers,body:await response.json()};
  }
  async function create(kind='writing',{course,owner=alice,...patch}={}){
    if(!course){const response=await call('/courses',{method:'POST',owner,body:{title:'Business fundamentals',provider:'Synthetic provider',syllabus:'The syllabus includes evidence-based recommendations.'}});assert.equal(response.status,201,JSON.stringify(response.body));course=response.body.item;}
    const writing=['writing','presentation','discussion'].includes(kind);
    const response=await call('/projects',{method:'POST',owner,body:{courseId:course.id,kind,title:writing?'A business recommendation':'Practice calculation',prompt:writing?'Explain the recommendation with evidence and an example.':'Solve 2x + 1 = 17. Show the calculation and check the answer.',rubric:writing?'Connect evidence to the recommendation.':'Show steps and check the calculation.',studentNotes:writing?'I recommend a practical approach because it helps the team act on the available evidence.':'I want to understand the method and check the calculation.',sources:[],...patch}});assert.equal(response.status,201,JSON.stringify(response.body));return{course,project:response.body.item};
  }
  const run=(project,action,extra={})=>call('/projects/'+project.id+'/run',{method:'POST',body:{revision:project.revision,action,requestId:randomUUID(),...extra}});
  return{DB,storage,provider,sourceCalls,env,call,create,run};
}
function httpEvidenceResponse({text='The supplied synthetic source explains the concept using a practical example. The source provides background material for evaluating the proposed business recommendation.',status=200,mediaType='text/html'}={}){return new Response(mediaType==='text/html'?'<html><head><title>Synthetic retrieved source</title></head><body><article>'+text+'</article></body></html>':text,{status,headers:{'Content-Type':mediaType}});}

