test('writing plan runs real adapter research and synthesis with source provenance and useful questions',async t=>{
  const f=fixture(t),{project}=await f.create();const result=await f.run(project,'plan');assert.equal(result.status,200,JSON.stringify(result.body));assert.equal(result.body.item.status,'ready');assert.equal(f.provider.calls.length,2);assert.equal(f.sourceCalls.length,1);
  assert.equal(f.provider.calls[0].body.tools[0].max_uses,3);assert.equal(f.provider.calls[0].body.max_tokens,6000);assert.deepEqual(f.provider.calls[0].body.thinking,{type:'between_tools'});assert.equal(f.provider.calls[0].body.output_config.effort,'low');
  const synthesis=f.provider.calls[1].body;assert.equal(synthesis.max_tokens,8192);assert.deepEqual(synthesis.thinking,{type:'adaptive'});assert.equal(synthesis.output_config.effort,'medium');assert(synthesis.output_config.format.schema);assert(f.provider.calls.every(call=>!call.body.tools?.some(tool=>tool.name==='web_fetch')));
  const context=JSON.parse(synthesis.messages[0].content);assert.equal(context.assignment.studentNotes,project.studentNotes);assert.equal(context.course.syllabus,'The syllabus includes evidence-based recommendations.');assert(context.sources[0].excerpt.includes('practical example'));
  assert.equal(result.body.item.artifact.sources[0].url,'https://www.cdc.gov/example-study');assert.equal(result.body.item.artifact.sources[0].origin,'server-https-fetch');assert.equal(result.body.item.artifact.sourceChecks.claimSupportVerified,false);assert.equal(result.body.item.artifact.sourceChecks.research.searches,1);assert(result.body.item.artifact.questions.length);
  assert.equal(result.headers.get('Cache-Control'),'private, no-store');assert.equal(result.headers.get('X-Robots-Tag'),'noindex, nofollow');assert(!JSON.stringify(result.body).includes('synthetic-learning-api-key'));
});
