function nativeCountFixture(){const calls=[];return{calls,fetcher:async(url,options)=>{const body=JSON.parse(options.body);calls.push({url,body});return Response.json({input_tokens:body.system?2000:100});}};}
function homeworkResponse({write=0,read=0,calculation}={}){return Response.json({stop_reason:'end_turn',usage:{input_tokens:200,output_tokens:100,cache_creation_input_tokens:write,cache_read_input_tokens:read},content:[{type:'text',text:JSON.stringify({summary:calculation?'The solution is x = '+calculation.solution+'.':'Solve and check the equation.',content:calculation?'The answer is x = '+calculation.solution+'.\n'+calculation.steps.join('\n')+'\nSubstitution gives '+calculation.leftValue+' on each side.':'Solve the current equation, then substitute the result to check it.',questions:[],checks:[],nextStep:'Try a similar equation.',quiz:[],flashcards:[],slides:[]})}]});}

