  const style=await f.call(path,{method:'POST',body:{rating:'nothelpful',reason:'unnatural_style'}});assert.equal(style.status,200,JSON.stringify(style.body));assert.equal(style.body.runUsage.feedback.reason,'unnatural_style');assert.equal((await f.call('/projects/'+project.id+'/history/'+requestId)).body.runUsage.feedback.reason,'unnatural_style');
  const clear=await f.call(path,{method:'POST',body:{rating:'clear'}});assert.equal(clear.status,200);assert.equal(clear.body.runUsage.feedback.rating,null);assert.equal(clear.body.runUsage.feedback.reason,null);
  const forged=randomUUID(),raw=f.storage.projects.get(f.storage.key(alice,project.id));raw.last_run_id=forged;f.storage.runs.set(f.storage.key(alice,forged),{user_id:alice,id:forged,project_id:project.id,action:'study',status:'completed',artifact:{content:'Own edited document'}});
