    const{project}=await f.create(kind,{prompt:'Explain the scientific concept accurately.',rubric:'',studentNotes:''}),result=await f.run(project,kind);assert.equal(result.status,200,JSON.stringify(result.body));const artifact=result.body.item.artifact;assert.equal(artifact.sourceChecks.research.retrievedSources,0);assert.equal(artifact.review.status,'needs-review');assert(artifact.review.flags.some(flag=>flag.kind==='research-evidence'&&flag.severity==='blocking'&&flag.nextAction));assert.equal(JSON.parse(f.provider.calls.at(-1).body.messages[0].content).evidencePolicy.researchRequired,true);
