test('partial assigned-source success survives autonomous HTTP fallback while failed URLs retain bounded status diagnostics',async t=>{
  const f=fixture(t),original=f.env.LEARNING_SOURCE_FETCH,good='https://reading.example.edu/good',bad='https://reading.example.edu/missing';f.env.LEARNING_SOURCE_FETCH=async(url,options)=>{if(url===bad){f.sourceCalls.push({url,options});return new Response('Private upstream error text must never be stored',{status:404});}return original(url,options);};const{project}=await f.create('study',{prompt:'Explain the business concept using reliable sources.',rubric:'',sources:[{id:'S4',url:good,title:'Good assigned reading',excerpt:'Student annotation'},{id:'S5',url:bad,title:'Unavailable assigned reading',excerpt:'Do not trust this pasted claim.'}]}),result=await f.run(project,'study');assert.equal(result.status,200,JSON.stringify(result.body));const artifact=result.body.item.artifact;assert(artifact.sources.some(source=>source.id==='S4'&&source.url===good));assert(artifact.sources.some(source=>source.url==='https://www.cdc.gov/example-study'));assert.equal(artifact.sourceChecks.research.rejectedSources[0].httpStatus,404);assert(artifact.sourceChecks.research.excludedSources.some(source=>source.id==='S5'&&source.httpStatus===404));assert(!JSON.stringify(artifact.sourceChecks).includes('Private upstream error'));assert(f.sourceCalls.length<=8);assert.equal(f.provider.calls.length,2);
});
